// ─── API ──────────────────────────────────────────────────────────────────────
const API_BASE = "https://86y86kc1e1.execute-api.us-east-1.amazonaws.com/prod";

const api = {
  get: async (path) => {
    const r = await fetch(`${API_BASE}${path}`);
    const d = await r.json();
    if (!r.ok) throw new Error(d.message || d.error || r.statusText);
    return d;
  },
  post: async (path, body) => {
    const r = await fetch(`${API_BASE}${path}`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    const d = await r.json();
    if (!r.ok) throw new Error(d.message || d.error || r.statusText);
    return d;
  },
  put: async (path, body) => {
    const r = await fetch(`${API_BASE}${path}`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    const d = await r.json();
    if (!r.ok) throw new Error(d.message || d.error || r.statusText);
    return d;
  },
  del: async (path) => {
    const r = await fetch(`${API_BASE}${path}`, { method: "DELETE" });
    const d = await r.json();
    if (!r.ok) throw new Error(d.message || d.error || r.statusText);
    return d;
  },
};


